#[derive(Debug, Clone, PartialEq, Eq)]
enum Exp {
    Const(i64),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

impl Exp {
    fn optimize(&self) -> Exp {
        match self {
            Exp::Const(_) | Exp::Var(_) => self.clone(),
            
            Exp::Plus(left, right) => {
                match (&**left, &**right) {
                    // Constant folding for addition
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                    
                    // Neutral element: 0 + e = e
                    (Exp::Const(0), _) => (**right).clone(),
                    
                    // Neutral element: e + 0 = e
                    (_, Exp::Const(0)) => (**left).clone(),
                    
                    // No optimization applies
                    _ => Exp::Plus(left.clone(), right.clone()),
                }
            }
            
            Exp::Mult(left, right) => {
                match (&**left, &**right) {
                    // Constant folding for multiplication
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                    
                    // Absorbing element: 0 * e = 0
                    (Exp::Const(0), _) => Exp::Const(0),
                    
                    // Absorbing element: e * 0 = 0
                    (_, Exp::Const(0)) => Exp::Const(0),
                    
                    // Neutral element: 1 * e = e
                    (Exp::Const(1), _) => (**right).clone(),
                    
                    // Neutral element: e * 1 = e
                    (_, Exp::Const(1)) => (**left).clone(),
                    
                    // No optimization applies
                    _ => Exp::Mult(left.clone(), right.clone()),
                }
            }
        }
    }
    
    fn eval(&self, store: &std::collections::HashMap<String, i64>) -> i64 {
        match self {
            Exp::Const(val) => *val,
            Exp::Var(name) => *store.get(name).unwrap_or(&-1),
            Exp::Plus(left, right) => left.eval(store) + right.eval(store),
            Exp::Mult(left, right) => left.eval(store) * right.eval(store),
        }
    }
}

